"""T07 (spec 02 §1): a HOI_DAP record's source document is generated by the
server at create time — a real text file under the registry's
``<root>/source_documents/`` directory (the ``uploads/`` id convention,
which the /content policy serves unconditionally), registered before the
record is written.

Acceptance covered here:

- a caller-supplied ``source_document_id`` on a HOI_DAP create is always
  overwritten by the server's generated ``uploads/hoi-dap-<record_id>`` id;
- the generated id is registered in the registry, is servable, and the
  file exists on disk under ``<root>/source_documents/`` containing the
  question/answer text;
- a non-HOI_DAP create leaves ``source_document_id`` untouched;
- creating a second HOI_DAP record with a distinct id does not raise
  ``FileExistsError`` from the registry — each id is deterministic from
  its own record id.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient

ROOT = Path(__file__).resolve().parents[2]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from config.settings import RAGSettings  # noqa: E402
from rag2025.src.app.lifecycle import (  # noqa: E402
    configure_canonical_record_store,
)
from src.infrastructure.canonical_record_store import CanonicalRecordStore  # noqa: E402
from src.infrastructure.source_document_registry import (  # noqa: E402
    SOURCE_DOCUMENTS_DIRNAME,
    SourceDocumentRegistry,
)
from src.routers.admin import router as admin_router  # noqa: E402

HOI_DAP_RECORD_ID = "HOI_DAP:tuyensinh:2026:q1"


def _headers(role: str) -> dict[str, str]:
    return {"X-Admin-Token": f"tok-{role}"}


def _configure(monkeypatch) -> None:
    monkeypatch.setenv(
        "ADMIN_IDENTITIES",
        json.dumps(
            [
                {"token": "tok-editor", "actor_id": "cb.editor", "role": "editor"},
                {"token": "tok-admin", "actor_id": "cb.admin", "role": "admin"},
            ]
        ),
    )
    monkeypatch.setenv("ADMIN_API_TOKEN", "shared-ops-token")


def _hoi_dap_body(source_document_id: str | None = "garbage-fabricated-id") -> dict:
    fields: dict = {
        "record_id": HOI_DAP_RECORD_ID,
        "record_type": "HOI_DAP",
        "version": 1,
        "admission_year": 2026,
        "effective_from": "2026-06-01",
        "status": "draft",
        "authority_level": "husc_official",
        "text": "Hỏi: năm nay xét nguyện vọng khi nào? Đáp: đến 15/7/2026.",
    }
    if source_document_id is not None:
        fields["source_document_id"] = source_document_id
    return fields


def _non_hoi_dap_body() -> dict:
    return {
        "record_id": "DIEM_CHUAN:NGANH:cntt:2026:t07",
        "record_type": "DIEM_CHUAN",
        "version": 1,
        "admission_year": 2026,
        "effective_from": "2026-06-01",
        "status": "draft",
        "authority_level": "husc_official",
        "source_document_id": "de-an-tuyen-sinh-2026",
        "text": "Điểm chuẩn ngành Công nghệ thông tin năm 2026 là 25,5.",
    }


def _expected_doc_id(record_id: str) -> str:
    """The sanitized document id the server derives from a record id.

    ``:`` ``/`` ``\\`` are all replaced with ``-`` so the id is a valid
    Windows file name; the ``uploads/`` prefix is the store-owned
    servable convention the /content policy opens.
    """
    safe = record_id.replace("\\", "-").replace("/", "-").replace(":", "-")
    return f"uploads/hoi-dap-{safe}.txt"


@pytest.fixture
def store_root(tmp_path: Path) -> Path:
    return tmp_path / "canonical_store"


@pytest.fixture
def app(store_root: Path, monkeypatch) -> FastAPI:
    _configure(monkeypatch)
    application = FastAPI()
    application.include_router(admin_router)
    configure_canonical_record_store(
        application, settings=RAGSettings(CANONICAL_STORE_ROOT=store_root)
    )
    return application


@pytest.fixture
def client(app: FastAPI) -> TestClient:
    with TestClient(app) as test_client:
        yield test_client


def test_hoi_dap_create_overwrites_caller_supplied_source_document_id(
    client: TestClient, store_root: Path
):
    """A fabricated caller id must not reach the student-facing citation."""
    response = client.post(
        "/admin/records",
        json={"record": _hoi_dap_body("garbage-fabricated-id")},
        headers=_headers("editor"),
    )
    assert response.status_code == 200, response.text
    stored = response.json()["record"]
    expected = _expected_doc_id(HOI_DAP_RECORD_ID)
    assert stored["source_document_id"] == expected

    reg = client.app.state.source_document_registry
    assert reg.is_registered(expected)
    # The /content policy must actually open this id from the citation chip.
    assert reg.is_servable(expected)
    # The blob lives under ``<root>/source_documents/`` (the ``uploads/``
    # convention), not under the registry's entry-JSON dir.
    content = reg.root / SOURCE_DOCUMENTS_DIRNAME / expected.removeprefix("uploads/")
    assert content.is_file(), f"expected {content} to exist"
    text = content.read_text(encoding="utf-8")
    assert "Hỏi: năm nay xét nguyện vọng khi nào?" in text
    assert "Đáp: đến 15/7/2026" in text


def test_non_hoi_dap_create_keeps_caller_source_document_id(client: TestClient):
    """Non-HOI_DAP creates are untouched: today's behaviour exactly."""
    response = client.post(
        "/admin/records",
        json={"record": _non_hoi_dap_body()},
        headers=_headers("editor"),
    )
    assert response.status_code == 200, response.text
    assert response.json()["record"]["source_document_id"] == "de-an-tuyen-sinh-2026"


def test_hoi_dap_distinct_records_do_not_raise_file_exists_error(
    client: TestClient,
):
    """Each HOI_DAP record maps to its own deterministic id; creating two
    distinct records never produces a second document for the same id, and
    a retry of the same record id is a version conflict at the store level
    (append-only), not a registry ``FileExistsError``.
    """
    first = client.post(
        "/admin/records",
        json={"record": _hoi_dap_body()},
        headers=_headers("editor"),
    )
    assert first.status_code == 200, first.text
    assert first.json()["record"]["source_document_id"] == (
        _expected_doc_id(HOI_DAP_RECORD_ID)
    )

    second_body = _hoi_dap_body()
    second_body["record_id"] = "HOI_DAP:tuyensinh:2026:q2"
    second = client.post(
        "/admin/records", json={"record": second_body}, headers=_headers("editor")
    )
    assert second.status_code == 200, second.text
    assert second.json()["record"]["source_document_id"] == (
        _expected_doc_id("HOI_DAP:tuyensinh:2026:q2")
    )

    reg = client.app.state.source_document_registry
    # Both ids registered, servable, with no FileExistsError raised for
    # either.
    expected_a = _expected_doc_id(HOI_DAP_RECORD_ID)
    expected_b = _expected_doc_id("HOI_DAP:tuyensinh:2026:q2")
    assert reg.is_registered(expected_a)
    assert reg.is_registered(expected_b)
    assert reg.is_servable(expected_a)
    assert reg.is_servable(expected_b)